var t=`0365-ribel`;var n=`world-0365`;var s=`LI`;var a=`western-europe`;var o=4;var r=32;var l={en:`Ribel`,ua:`Рібель`};var d={en:`A traditional Liechtenstein dish made with corn grits, whole cow milk, apple sauce. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Ліхтенштейн. Основні інгредієнти: кукурудзяна крупа, цільне коров'яче молоко, яблучне пюре. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`corn-grits`,330,`g`],[`whole-cow-milk`,700,`ml`],[`water`,300,`ml`],[`table-salt`,4,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`unsalted-butter`,75,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`apple-sauce`,140,`g`]]}];var g={slug:t,id:n,country:`LI`,region:a,servings:4,minutes:32,title:l,text:d,steps:u};export{s as country,g as default,n as id,r as minutes,a as region,o as servings,t as slug,u as steps,d as text,l as title};